package com.clinic.service;
import com.clinic.config.Database;import com.clinic.util.Sql;import com.clinic.exception.AppException;import org.mindrot.jbcrypt.BCrypt;
import java.sql.*;import java.util.*;import java.time.*;
public final class PortalService {
 public static void admin(String role){if(!"ADMIN".equals(role))throw new AppException(403,"Administrator access required.");}
 private final com.clinic.dao.IDoctorDAO doctorDAO=new com.clinic.dao.impl.JdbcDoctorDAO();
 private final com.clinic.dao.IPatientDAO patientDAO=new com.clinic.dao.impl.JdbcPatientDAO();
 public List<Map<String,Object>> doctors(Map<String,String> f)throws SQLException{try(var c=Database.getConnection()){return doctorDAO.search(c,f.getOrDefault("q",""),f.getOrDefault("specialty",""),size(f),offset(f));}}
 public void doctor(long actor,String role,long userId,Map<String,Object>b)throws SQLException{admin(role);String specialty=str(b,"specialization",100,true),description=str(b,"profileDescription",4000,false);double fee=Double.parseDouble(Objects.toString(b.get("consultationFee"),"0"));if(!Double.isFinite(fee)||fee<0||fee>1000000)throw new AppException(400,"Invalid consultation fee.");try(var c=Database.getConnection()){c.setAutoCommit(false);try{doctorDAO.update(c,userId,specialty,fee,description);Sql.audit(c,actor,"DOCTOR_PROFILE_UPDATED","USER",userId);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public List<Map<String,Object>> users(String role,Map<String,String> f)throws SQLException{admin(role);try(var c=Database.getConnection()){return Sql.query(c,"SELECT u.user_id AS id,u.name,u.email,u.role,u.account_status AS status,u.created_at AS createdAt,p.patient_id AS patientId,d.doctor_id AS doctorId,d.specialization,d.consultation_fee AS consultationFee,d.profile_description AS profileDescription FROM users u LEFT JOIN patients p ON p.user_id=u.user_id LEFT JOIN doctors d ON d.user_id=u.user_id WHERE (u.name LIKE ? OR u.email LIKE ?) AND u.role LIKE ? ORDER BY u.created_at DESC LIMIT ? OFFSET ?","%"+f.getOrDefault("q","")+"%","%"+f.getOrDefault("q","")+"%","%"+f.getOrDefault("role","")+"%",size(f),offset(f));}}
 public Map<String,Object> profile(long id)throws SQLException{try(var c=Database.getConnection()){return Sql.one(c,"SELECT u.user_id AS id,u.name,u.email,u.role,p.patient_id AS patientId,p.date_of_birth AS dateOfBirth,p.blood_group AS bloodGroup,p.emergency_contact AS emergencyContact,p.allergies,p.medications,d.doctor_id AS doctorId,d.specialization,d.consultation_fee AS consultationFee,d.profile_description AS profileDescription FROM users u LEFT JOIN patients p ON p.user_id=u.user_id LEFT JOIN doctors d ON d.user_id=u.user_id WHERE u.user_id=?",id);}}
 public void profile(long id,Map<String,Object> b)throws SQLException{
  String name=str(b,"name",120,true);String birth=str(b,"dateOfBirth",10,false);if(!birth.isBlank()&&LocalDate.parse(birth).isAfter(LocalDate.now()))throw new AppException(400,"Date of birth cannot be in the future.");
  try(var c=Database.getConnection()){c.setAutoCommit(false);try{Sql.update(c,"UPDATE users SET name=? WHERE user_id=?",name,id);patientDAO.update(c,id,birth,str(b,"bloodGroup",10,false),str(b,"emergencyContact",100,false),str(b,"allergies",10000,false),str(b,"medications",10000,false));c.commit();}catch(Exception e){c.rollback();throw e;}}
 }
 public void password(long id,Map<String,Object>b)throws SQLException{String next=str(b,"newPassword",100,true);AuthService.validatePassword(next);String current=str(b,"currentPassword",100,true);try(var c=Database.getConnection()){c.setAutoCommit(false);try{var u=Sql.one(c,"SELECT password_hash AS hash FROM users WHERE user_id=? FOR UPDATE",id);if(u==null||current.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72||!BCrypt.checkpw(current,(String)u.get("hash")))throw new AppException(400,"The current password is incorrect.");Sql.update(c,"UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE user_id=?",BCrypt.hashpw(next,BCrypt.gensalt(12)),id);Sql.audit(c,id,"PASSWORD_CHANGED","USER",id);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public void userStatus(long actor,String role,long id,String status)throws SQLException{admin(role);if(actor==id)throw new AppException(400,"You cannot deactivate your own account.");if(!Set.of("ACTIVE","INACTIVE").contains(status))throw new AppException(400,"Invalid status.");try(var c=Database.getConnection()){c.setAutoCommit(false);try{if(Sql.update(c,"UPDATE users SET account_status=? WHERE user_id=? AND role<>'ADMIN'",status,id)!=1)throw new AppException(400,"Only patient and doctor accounts can be updated here.");Sql.audit(c,actor,"ACCOUNT_"+status,"USER",id);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 public List<Map<String,Object>> notifications(long id)throws SQLException{try(var c=Database.getConnection()){return Sql.query(c,"SELECT notification_id AS id,title,message,notification_type AS type,read_status AS readStatus,created_at AS createdAt FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100",id);}}
 public void readNotifications(long id)throws SQLException{try(var c=Database.getConnection()){Sql.update(c,"UPDATE notifications SET read_status=TRUE WHERE user_id=?",id);}}
 public List<Map<String,Object>> audit(String role,Map<String,String> f)throws SQLException{admin(role);try(var c=Database.getConnection()){return Sql.query(c,"SELECT a.audit_id AS id,u.name AS actor,a.action,a.entity_type AS entityType,a.entity_id AS entityId,a.metadata,a.created_at AS createdAt FROM audit_logs a LEFT JOIN users u ON a.actor_user_id=u.user_id ORDER BY a.audit_id DESC LIMIT ? OFFSET ?",size(f),offset(f));}}
 public Map<String,Object> settings()throws SQLException{try(var c=Database.getConnection()){var result=new LinkedHashMap<String,Object>();for(var row:Sql.query(c,"SELECT setting_key AS k,setting_value AS v FROM clinic_settings"))result.put((String)row.get("k"),row.get("v"));result.put("specialties",Sql.query(c,"SELECT specialty_id AS id,name FROM specialties ORDER BY name"));return result;}}
 public void settings(long actor,String role,Map<String,Object> b)throws SQLException{admin(role);Set<String> keys=Set.of("cancellation_hours","booking_days","reminder_hours","appointment_duration","clinic_name","working_start","working_end","triage_priority_order");
  try(var c=Database.getConnection()){c.setAutoCommit(false);try{Sql.query(c,"SELECT doctor_id FROM doctors ORDER BY doctor_id FOR UPDATE");for(var e:b.entrySet()){if(!keys.contains(e.getKey()))continue;String v=String.valueOf(e.getValue()).strip();if(v.length()>200)throw new AppException(400,"Setting too long.");if(Set.of("cancellation_hours","booking_days","reminder_hours","appointment_duration").contains(e.getKey())){int n=Integer.parseInt(v);if(n<0||n>365||e.getKey().equals("reminder_hours")&&(n<1||n>168)||e.getKey().equals("appointment_duration")&&(n<5||n>120))throw new AppException(400,"Setting is outside the allowed range.");}if(e.getKey().startsWith("working_"))LocalTime.parse(v);if(e.getKey().equals("triage_priority_order")&&(v.split(",").length!=3||!new HashSet<>(Arrays.asList(v.split(","))).equals(Set.of("EMERGENCY","URGENT","ROUTINE"))))throw new AppException(400,"Use all three triage categories exactly once.");int updated=Sql.update(c,"UPDATE clinic_settings SET setting_value=? WHERE setting_key=?",v,e.getKey());if(updated==0)Sql.insert(c,"INSERT INTO clinic_settings(setting_key,setting_value) VALUES(?,?)",e.getKey(),v);}
   if(b.containsKey("newSpecialty")){String n=str(b,"newSpecialty",100,false);if(!n.isBlank())Sql.insert(c,"INSERT INTO specialties(name) VALUES(?)",n);}
   var hours=Sql.query(c,"SELECT setting_key AS k,setting_value AS v FROM clinic_settings WHERE setting_key IN ('working_start','working_end')");String start="09:00",end="18:00";for(var h:hours){if(h.get("k").equals("working_start"))start=(String)h.get("v");else end=(String)h.get("v");}if(!LocalTime.parse(start).isBefore(LocalTime.parse(end)))throw new AppException(400,"Clinic opening time must precede closing time.");if(Sql.one(c,"SELECT appointment_id FROM appointments WHERE appointment_date>=CURRENT_DATE AND status IN ('BOOKED','CONFIRMED','CHECKED_IN','IN_PROGRESS') AND (start_time<? OR end_time>?) LIMIT 1",start,end)!=null)throw new AppException(409,"These clinic hours conflict with existing appointments.");Sql.audit(c,actor,"SETTINGS_UPDATED","CLINIC",0);c.commit();}catch(Exception e){c.rollback();throw e;}}
 }
 public Map<String,Object> reports(String role,Map<String,String> f)throws SQLException{admin(role);String from=f.getOrDefault("from",LocalDate.now().minusDays(29).toString()),to=f.getOrDefault("to",LocalDate.now().toString());if(LocalDate.parse(from).isAfter(LocalDate.parse(to)))throw new AppException(400,"The report start date must precede the end date.");try(var c=Database.getConnection()){var out=new LinkedHashMap<String,Object>();out.put("daily",Sql.query(c,"SELECT appointment_date AS date,COUNT(*) AS count FROM appointments WHERE appointment_date BETWEEN ? AND ? GROUP BY appointment_date ORDER BY appointment_date",from,to));out.put("status",Sql.query(c,"SELECT status,COUNT(*) AS count FROM appointments WHERE appointment_date BETWEEN ? AND ? GROUP BY status",from,to));out.put("workload",Sql.query(c,"SELECT u.name AS doctor,COUNT(*) AS count,SUM(CASE WHEN a.status='COMPLETED' THEN 1 ELSE 0 END) AS completed FROM appointments a JOIN doctors d ON d.doctor_id=a.doctor_id JOIN users u ON u.user_id=d.user_id WHERE a.appointment_date BETWEEN ? AND ? GROUP BY u.user_id,u.name",from,to));out.put("registrations",Sql.query(c,"SELECT DATE(created_at) AS date,COUNT(*) AS count FROM users WHERE role='PATIENT' AND DATE(created_at) BETWEEN ? AND ? GROUP BY DATE(created_at)",from,to));out.put("specialties",Sql.query(c,"SELECT d.specialization AS specialty,COUNT(*) AS count FROM appointments a JOIN doctors d ON d.doctor_id=a.doctor_id WHERE a.appointment_date BETWEEN ? AND ? GROUP BY d.specialization",from,to));out.put("from",from);out.put("to",to);return out;}}
 public Map<String,Object> dashboard(long id,String role)throws SQLException{
  String scope=role.equals("PATIENT")?"a.patient_id IN (SELECT patient_id FROM patients WHERE user_id=?)":role.equals("DOCTOR")?"a.doctor_id IN (SELECT doctor_id FROM doctors WHERE user_id=?)":"? > 0";
  try(var c=Database.getConnection()){var out=new LinkedHashMap<String,Object>();var metrics=new ArrayList<Map<String,Object>>();if(role.equals("ADMIN")){metrics.add(metric(c,"Total patients","SELECT COUNT(*) AS n FROM patients"));metrics.add(metric(c,"Active doctors","SELECT COUNT(*) AS n FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE u.account_status='ACTIVE'"));}
   metrics.add(metric(c,"Today's appointments","SELECT COUNT(*) AS n FROM appointments a WHERE "+scope+" AND appointment_date=CURRENT_DATE AND status<>'CANCELLED'",id));metrics.add(metric(c,"Upcoming appointments","SELECT COUNT(*) AS n FROM appointments a WHERE "+scope+" AND TIMESTAMP(appointment_date,start_time)>=CURRENT_TIMESTAMP AND status IN ('BOOKED','CONFIRMED')",id));metrics.add(metric(c,"Completed visits","SELECT COUNT(*) AS n FROM appointments a WHERE "+scope+" AND status='COMPLETED'",id));metrics.add(metric(c,"Cancelled appointments","SELECT COUNT(*) AS n FROM appointments a WHERE "+scope+" AND status='CANCELLED'",id));
   metrics.add(metric(c,"No-show visits","SELECT COUNT(*) AS n FROM appointments a WHERE "+scope+" AND status='NO_SHOW'",id));if(!role.equals("PATIENT"))metrics.add(metric(c,"Waiting patients","SELECT COUNT(*) AS n FROM appointments a JOIN triage_entries t ON t.appointment_id=a.appointment_id WHERE "+scope+" AND t.queue_status='WAITING'",id));out.put("metrics",metrics);out.put("appointments",Sql.query(c,"SELECT a.appointment_id AS id,p.patient_id AS patientId,pu.name AS patientName,d.doctor_id AS doctorId,du.name AS doctorName,d.specialization,a.appointment_date AS date,a.start_time AS startTime,a.end_time AS endTime,a.status,a.reason_for_visit AS reason FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN users pu ON pu.user_id=p.user_id JOIN doctors d ON d.doctor_id=a.doctor_id JOIN users du ON du.user_id=d.user_id WHERE "+scope+" AND appointment_date>=CURRENT_DATE AND status IN ('BOOKED','CONFIRMED','CHECKED_IN','IN_PROGRESS') ORDER BY appointment_date,start_time LIMIT 8",id));out.put("series",Sql.query(c,"SELECT appointment_date AS date,COUNT(*) AS count FROM appointments a WHERE "+scope+" AND appointment_date BETWEEN DATE_SUB(CURRENT_DATE,INTERVAL 6 DAY) AND CURRENT_DATE GROUP BY appointment_date ORDER BY appointment_date",id));out.put("activity",notifications(id));return out;
  }
 }
 private Map<String,Object> metric(Connection c,String label,String sql,Object...args)throws SQLException{return Map.of("label",label,"value",Sql.one(c,sql,args).get("n"));}
 public List<Map<String,Object>> history(long id,String role,long appointmentId)throws SQLException{try(var c=Database.getConnection()){var a=Sql.one(c,"SELECT p.user_id AS patientUser,d.user_id AS doctorUser FROM appointments a JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id WHERE a.appointment_id=?",appointmentId);if(a==null)throw new AppException(404,"Appointment not found.");if(!role.equals("ADMIN")&&((Number)a.get(role.equals("PATIENT")?"patientUser":"doctorUser")).longValue()!=id)throw new AppException(403,"Access denied.");return Sql.query(c,"SELECT old_status AS oldStatus,new_status AS newStatus,change_reason AS reason,created_at AS createdAt FROM appointment_history WHERE appointment_id=? ORDER BY history_id DESC",appointmentId);}}
 public static String str(Map<String,Object>b,String k,int max,boolean required){String s=Objects.toString(b.get(k),"").strip();if(s.length()>max||required&&s.isEmpty())throw new AppException(400,"Please provide a valid "+k+".");return s;}
 private static int size(Map<String,String> f){return Math.min(100,Math.max(1,Integer.parseInt(f.getOrDefault("pageSize","25"))));}
 private static int offset(Map<String,String>f){return (Math.min(100000,Math.max(1,Integer.parseInt(f.getOrDefault("page","1"))))-1)*size(f);}
}
